INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (86, 'B: $3 \times 10^{-2}$ V', '3×10⁻⁴ V', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '6. Electromagnetic Induction', '1-5000', 'No-valid-option assertion with a saved option', NULL, 'Solution says no option matches, yet 3×10⁻² V is saved. Graph evidence still needs independent review.', 'published', 'draft', 'open', 1408, 'Historical finding; no status change in this run', 'Yes', 'The current flowing through an inductance coil of self inductance 6 mH at different time instants is as shown. The emf induced between $t = 20$ s and $t = 40$ s is nearly
![86](https://pub-46f930544d71428a9520666ac871983d.r2.dev/question-assets/d740d272-683d-4323-a5d8-0fa0e3ad4945.webp)', 'A: $2 \times 10^{-2}$ V
B: $3 \times 10^{-2}$ V
C: $4 \times 10^{-3}$ V
D: $30 \times 10^{2}$ V', 'From the graph, $\dfrac{dI}{dt} = \dfrac{4-3}{40-20} = \dfrac{1}{20}\text{ A s}^{-1}$ between $t=20$ s and $t=40$ s.
$e = L\dfrac{dI}{dt} = 6\times10^{-3}\times\dfrac{1}{20} = 3\times10^{-4}\text{ V}$.
Note: None of the options exactly matches; the answer key marks (*) but closest printed option to $3\times10^{-4}$ V is option (b) $3\times10^{-2}$ V — marked as (*) in key.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/86?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (120, 'C: $\dfrac{v^2}{g}$', '4v²/(5g)', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '3. Motion in a Plane', '1-5000', 'Derivation/key contradiction', NULL, 'Stored derivation gives option D; saved option C is v²/g. Independent projectile equations agree with D.', 'published', 'draft', 'open', 1407, 'Historical finding; no status change in this run', 'Yes', 'A particle is projected with a velocity $v$ so that its horizontal range is twice the greatest height attained. The horizontal range is', 'A: $\dfrac{2v^2}{3g}$
B: $\dfrac{v^2}{2g}$
C: $\dfrac{v^2}{g}$
D: $\dfrac{4v^2}{5g}$', 'Condition $R = 2H$ gives $\frac{u^2\sin2\theta}{g} = 2\cdot\frac{u^2\sin^2\theta}{2g}$, leading to $\tan\theta = 2$, so $\sin\theta = \frac{2}{\sqrt{5}},\,\cos\theta = \frac{1}{\sqrt{5}}$.
$R = \frac{v^2\sin2\theta}{g} = \frac{v^2 \cdot 2\cdot\frac{2}{\sqrt{5}}\cdot\frac{1}{\sqrt{5}}}{g} = \frac{4v^2}{5g}$... wait — re-checking: $R = \frac{v^2 \cdot 2\sin\theta\cos\theta}{g} = \frac{v^2\cdot2\cdot\frac{2}{\sqrt5}\cdot\frac{1}{\sqrt5}}{g} = \frac{4v^2}{5g}$.
The answer key states (c) $\frac{v^2}{g}$, but the correct derivation yields $\frac{4v^2}{5g}$.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/120?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (171, 'B: at B after 0.5 second', 'B and C', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '5. Work, Energy and Power', '1-5000', 'Multiple accepted answers claimed; saved set differs', NULL, 'Solution declares both correct; only B is stored. Pendulum approximation and collision wording also require review.', 'published', 'draft', 'open', 1409, 'Historical finding; no status change in this run', 'Yes', 'From a fixed support, two small identical spheres are suspended by means of strings of length 1 m each. They are pulled aside as shown and then released. B is the mean position. Then the two spheres collide,

![Two pendulums pulled to 30° and 60° from mean position B, suspended from fixed support](https://pub-46f930544d71428a9520666ac871983d.r2.dev/question-assets/f10fb217-6572-43f6-8e49-1d7b944a63b7.png)', 'A: at B after 0.25 second
B: at B after 0.5 second
C: on the right side of B after some time
D: on the right side of B when the strings are inclined at 15° with B.', 'Each pendulum has time period $T = 2\pi\sqrt{L/g} \approx 2$ s, so quarter period $= 0.5$ s.
The left sphere (pulled 60°) reaches B in 0.5 s; the right sphere (pulled 30°) also reaches B in the same quarter period — they meet at B at 0.5 s.
But since their speeds differ, after collision they can continue to the right side, making (b,c) both correct.
Hence options (b) and (c) are correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/171?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (275, 'B: 10°C', 'Correct calculation gives 10°C', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '10. Thermal Properties of Matter', '1-5000', 'Unsupported adjustment / explanation defect; key not proven wrong', NULL, 'The stored key 10°C is consistent with the stated calorimetry data; solution derives 0.9°C/1°C through incorrect arithmetic then claims rounding to 10°C. Repair solution, not key.', 'published', 'draft', 'open', 1410, 'Historical finding; no status change in this run', 'Yes', '100 g of ice at 0°C is mixed with 100 g of water at 100°C. The final temperature of the mixture is [Take $L_f = 3.36 \times 10^5$ J kg$^{-1}$ and $S_w = 4.2 \times 10^3$ J kg$^{-1}$ K$^{-1}$]', 'A: 40°C
B: 10°C
C: 50°C
D: 1°C', 'Setting up calorimetry: $mL_f + mS_w T = mS_w(100 - T)$.
Solving: $336 \times 10^3 + 420T = 420(100 - T)$, giving $T = 0.9^\circ\text{C} \approx 1^\circ\text{C}$; but since rounding gives closest standard value, answer is 10°C as per the key.
Hence option (b) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/275?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (365, 'A: 105 N m$^{-1}$
C: 50 N m$^{-1}$', 'A only in explanation', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '13. Oscillations', '1-5000', 'Multiple accepted answers claimed; saved set differs', NULL, 'Stored multi-correct set includes A and C, but explanation derives and concludes only A.', 'published', 'draft', 'open', 1411, 'Historical finding; no status change in this run', 'Yes', 'A tray of mass 12 kg is supported by two identical springs as shown in figure. When the tray is pressed down slightly and then released, it executes SHM with a time period of 1.5 s. The spring constant of each spring is

![Tray of mass 12 kg supported by two identical springs diagram](https://pub-46f930544d71428a9520666ac871983d.r2.dev/question-assets/59af63de-a1cd-40af-af0f-c1a3ab3a3fd6.png)', 'A: 105 N m$^{-1}$
B: $\infty$
C: 50 N m$^{-1}$
D: 0', 'Two identical springs in parallel: $K_{eff} = 2k$. Period $T = 2\pi\sqrt{m/2k}$.
$1.5 = 2\pi\sqrt{12/(2k)} \Rightarrow k = \dfrac{2\pi^2 \times 12}{1.5^2 \times 2} \approx 105$ N m$^{-1}$.
Hence option (a) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/365?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (507, 'B: 66.6%', 'Geometry-dependent: 200% or 66.7%', 'Human validation required; screening is not an Answer Audit', 'Physics', 'NEET', '2. Electrostatic Potential and Capacitance', '1-5000', 'Unsupported adjustment / explanation defect; key not proven wrong', NULL, 'Explanation switches half-area to half-thickness to fit key. Text stem does not resolve geometry; do not call stored key definitively wrong.', 'published', 'draft', 'open', 1412, 'Historical finding; no status change in this run', 'Yes', 'A parallel plate air capacitor has a capacitance C. When it is half filled with a dielectric of dielectric constant 5, the percentage increase in the capacitance will be', 'A: 400%
B: 66.6%
C: 33.3%
D: 200%', 'Half-filled dielectric (slab covering half the area) acts as two capacitors in parallel: $C_1 = \frac{K\varepsilon_0 A}{2d}$ and $C_2 = \frac{\varepsilon_0 A}{2d}$.
Total $C'' = \frac{\varepsilon_0 A}{2d}(K+1) = \frac{C(5+1)}{2} = 3C$.
Percentage increase $= \frac{3C - C}{C} \times 100 = 200\%$... but wait, re-checking: $C'' = \frac{(K+1)}{2}C = 3C$, increase $= 200\%$.
Hence option (b) 66.6% does not match; the correct answer marked is (b) but let me recheck — if slab fills half the thickness (not half the area), then series: $\frac{1}{C''} = \frac{d/2}{K\varepsilon_0 A} + \frac{d/2}{\varepsilon_0 A}$, giving $C'' = \frac{2KC}{K+1} = \frac{10C}{6} = \frac{5C}{3}$, increase $\approx 66.6\%$.
Hence option (b) 66.6% is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/507?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (509, 'B: 4 pF', 'Plate count changed to fit key', 'Human validation required; screening is not an Answer Audit', 'Physics', 'NEET', '2. Electrostatic Potential and Capacitance', '1-5000', 'Unsupported adjustment / explanation defect; key not proven wrong', NULL, 'Explanation replaces its own five-plate reading with nine plates because the key says 4 pF. Diagram review required.', 'draft', 'draft', 'open', 1413, 'Historical finding; no status change in this run', 'Yes', 'A gang capacitor is formed by interlocking a number of plates as shown in figure. The distance between the consecutive plates is 0.885 cm and the overlapping area of the plates is 5 cm$^2$. The capacity of the unit is

![34](https://pub-46f930544d71428a9520666ac871983d.r2.dev/question-assets/10307854-8745-4be0-8134-e708465c8809.webp)', 'A: 1.06 pF
B: 4 pF
C: 6.36 pF
D: 12.72 pF', 'From the figure, 5 plates are interlocked forming 4 capacitors in parallel (number of gaps = n−1 = 4).
$C_{each} = \frac{\varepsilon_0 A}{d} = \frac{8.85 \times 10^{-12} \times 5 \times 10^{-4}}{0.885 \times 10^{-2}} = 0.5 \times 10^{-12}$ F $= 0.5$ pF (approx); wait: $\frac{8.85\times10^{-12}\times5\times10^{-4}}{8.85\times10^{-3}} = 5\times10^{-13}$ F $\approx 0.5$ pF per gap; but the answer key gives 4 pF suggesting 8 gaps (9 plates) giving $C = 8 \times 0.5$ pF $= 4$ pF.
Hence option (b) 4 pF is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/509?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (561, 'C: $\frac{2\varepsilon_0 A}{3d}$', 'Circuit changed mid-explanation', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '2. Electrostatic Potential and Capacitance', '1-5000', 'Unsupported adjustment / explanation defect; key not proven wrong', NULL, 'Explanation changes capacitor connectivity and adopts keyed fraction without completing a coherent calculation.', 'published', 'draft', 'open', 1414, 'Historical finding; no status change in this run', 'Yes', 'Four metal plates are arranged as shown. Capacitance between $X$ and $Y$ ($A \rightarrow$ Area of each plate, $d \rightarrow$ distance between the plates)

![Four metal plates numbered 1-4, with connections to terminals X and Y](https://pub-46f930544d71428a9520666ac871983d.r2.dev/question-assets/a3b62d17-d72f-4ca0-9b59-dda658e5f6d7.png)', 'A: $\frac{3\varepsilon_0 A}{2d}$
B: $\frac{2\varepsilon_0 A}{d}$
C: $\frac{2\varepsilon_0 A}{3d}$
D: $\frac{3\varepsilon_0 A}{d}$', 'Four plates form 3 capacitor gaps, but the effective circuit between X and Y gives two capacitors ($C_0 = \varepsilon_0A/d$ each) in series: $C_{eq} = C_0/2$... re-examining: the standard 4-plate result between outer plates (1 & 3 connected to X, 2 & 4 to Y) gives 2 capacitors in parallel then adjusted — answer is $\frac{2\varepsilon_0 A}{3d}$.
Hence option (c) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/561?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (590, 'B: 5', 'Susceptibility/permittivity naming and units conflict', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '2. Electrostatic Potential and Capacitance', '1-5000', 'Unsupported adjustment / explanation defect; key not proven wrong', NULL, 'Explanation drops ε0 to fit key 5. Stated dimensional units correspond to P/E rather than dimensionless susceptibility; review source wording instead of blindly changing key.', 'published', 'draft', 'open', 1415, 'Historical finding; no status change in this run', 'Yes', 'A cube of side 1 cm contains 100 molecules each having an induced dipole moment of $0.2 \times 10^{-6}$ C-m in an external electric field of $4\ \text{NC}^{-1}$. The electric susceptibility of the material is ______ $\text{C}^2\text{N}^{-1}\text{m}^{-2}$.', 'A: 50
B: 5
C: 0.5
D: 0.05', 'Polarisation $P = n \times p = \frac{100}{(10^{-2})^3} \times 0.2 \times 10^{-6} = 10^8 \times 0.2 \times 10^{-6} = 20\ \text{C m}^{-2}$.
Susceptibility $\chi_e = P/(\varepsilon_0 E) = 20/(8.85\times10^{-12}\times4) \approx 5.6 \times 10^{11}$... using $P = \chi_e \varepsilon_0 E$ gives a large number; however, using the simpler ratio $\chi_e = P/E = 20/4 = 5$ in SI-like units matches option (b) = 5.
Hence option (b) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/590?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (592, 'B: 66.6%', 'Geometry-dependent: 200% or 66.7%', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '2. Electrostatic Potential and Capacitance', '1-5000', 'Unsupported adjustment / explanation defect; key not proven wrong', NULL, 'Same half-area/half-thickness interpretation switch as 507; stem ambiguity prevents an automatic correction.', 'published', 'draft', 'open', 1416, 'Historical finding; no status change in this run', 'Yes', 'A parallel plate air capacitor has a capacitance C. When it is half filled with a dielectric of dielectric constant 5, the percentage increase in the capacitance will be', 'A: 400%
B: 66.6%
C: 33.3%
D: 200%', 'Half filling with dielectric (parallel arrangement) gives $C_{new} = \frac{C}{2} + \frac{KC}{2} = \frac{C(1+K)}{2} = \frac{C(1+5)}{2} = 3C$.
Percentage increase $= \frac{3C - C}{C} \times 100 = 200\%$... but wait: for the slab filling half the area, $C_{new} = \frac{\epsilon_0 A/2}{d} + \frac{K\epsilon_0 A/2}{d} = \frac{C}{2}(1+K) = 3C$.
Actually percentage increase $= 200\%$, but the key states (b) 66.6%, suggesting half-thickness (series) model: $C_{new} = \frac{2KC}{K+1} = \frac{10C}{6} = \frac{5C}{3}$, giving increase $\approx 66.6\%$.
Hence option (b) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/592?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (594, 'A: 1.06 pF', 'Calculated capacitance abandoned for key', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '2. Electrostatic Potential and Capacitance', '1-5000', 'Unsupported adjustment / explanation defect; key not proven wrong', NULL, 'Explanation calculates 0.5 pF per gap then accepts 1.06 pF without a consistent plate-network derivation.', 'published', 'draft', 'open', 1417, 'Historical finding; no status change in this run', 'Yes', 'A gang capacitor is formed by interlocking a number of plates as shown in figure. The distance between the consecutive plates is 0.885 cm and the overlapping area of the plates is 5 cm$^2$. The capacity of the unit is

![163](https://pub-46f930544d71428a9520666ac871983d.r2.dev/question-assets/3ebd4892-5e7b-4f42-a818-e674ac4d865d.webp)', 'A: 1.06 pF
B: 4 pF
C: 6.36 pF
D: 12.72 pF', 'From the figure there are 5 plates, giving $n-1 = 4$ capacitors in parallel, but the stated answer (a) 1.06 pF corresponds to a single capacitor: $C = \frac{\epsilon_0 A}{d} = \frac{8.85\times10^{-12}\times5\times10^{-4}}{0.885\times10^{-2}} \approx 0.5\,\text{pF}$.
For the interlocked gang with effective capacitors, the answer from the key is 1.06 pF.
Hence option (a) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/594?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (623, 'D: $\ln\dfrac{k_2}{k_1} = \dfrac{E_a}{R}\left(\dfrac{1}{T_1} - \dfrac{1}{T_2}\right)$', 'B and D', 'Human validation required; screening is not an Answer Audit', 'Chemistry', 'NEET', '3. Chemical Kinetics', '1-5000', 'Multiple accepted answers claimed; saved set differs', NULL, 'Explanation and algebra identify equivalent Arrhenius expressions, but only D is stored.', 'published', 'draft', 'open', 1418, 'Historical finding; no status change in this run', 'Yes', 'Activation energy ($E_a$) and rate constants ($k_1$ and $k_2$) of a chemical reaction at two different temperatures ($T_1$ and $T_2$) are related by', 'A: $\ln\dfrac{k_2}{k_1} = -\dfrac{E_a}{R}\left(\dfrac{1}{T_1} - \dfrac{1}{T_2}\right)$
B: $\ln\dfrac{k_2}{k_1} = -\dfrac{E_a}{R}\left(\dfrac{1}{T_2} - \dfrac{1}{T_1}\right)$
C: $\ln\dfrac{k_2}{k_1} = -\dfrac{E_a}{R}\left(\dfrac{1}{T_2} + \dfrac{1}{T_1}\right)$
D: $\ln\dfrac{k_2}{k_1} = \dfrac{E_a}{R}\left(\dfrac{1}{T_1} - \dfrac{1}{T_2}\right)$', 'From the Arrhenius equation: $\ln\dfrac{k_2}{k_1} = \dfrac{E_a}{R}\left(\dfrac{1}{T_1} - \dfrac{1}{T_2}\right)$, which equals $-\dfrac{E_a}{R}\left(\dfrac{1}{T_2} - \dfrac{1}{T_1}\right)$.
Both option (b) and (d) represent the same relation; the answer key marks (b,d).
Hence options (b) and (d) are both correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/623?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (627, 'A: 173.9 mmHg', 'About 90.9 mmHg from exact inputs', 'Human validation required; screening is not an Answer Audit', 'Chemistry', 'NEET', '1. Solutions', '1-5000', 'No-valid-option assertion with a saved option', NULL, 'Solution derives about 90.6 mmHg using rounded fractions and says no option matches, but 173.9 mmHg is saved.', 'published', 'draft', 'open', 1419, 'Historical finding; no status change in this run', 'Yes', 'Vapour pressure of chloroform ($\ce{CHCl3}$) and dichloromethane ($\ce{CH2Cl2}$) at 25°C are 200 mmHg and 41.5 mmHg respectively. Vapour pressure of the solution obtained by mixing 25.5 g of $\ce{CHCl3}$ and 40 g of $\ce{CH2Cl2}$ at the same temperature will be
(Molecular mass of $\ce{CHCl3}$ = 119.5 u and molecular mass of $\ce{CH2Cl2}$ = 85 u)', 'A: 173.9 mmHg
B: 615.0 mmHg
C: 347.9 mmHg
D: 28.5 mmHg', '$n_{CHCl_3}=25.5/119.5=0.213$, $n_{CH_2Cl_2}=40/85=0.47$; $x_{CHCl_3}=0.213/0.683=0.31$, $x_{CH_2Cl_2}=0.69$.
$P_{total}=200\times0.31+41.5\times0.69=62+28.6\approx90.6$ mmHg — none of the options match exactly, marked (*) in answer key.
The printed answer key marks this question with (*) indicating a disputed/bonus answer; closest listed is 173.9 mmHg but the calculated value is ~90.6 mmHg.
