INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (936, 'B: 9 : 11', '6:5', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '9. Ray Optics and Optical Instruments', '1-5000', 'Derivation/key contradiction', NULL, 'Solution repeatedly calculates 6:5, but saved key is 9:11.', 'published', 'draft', 'open', 1421, 'Historical finding; no status change in this run', 'Yes', 'A prism of certain angle deviates the red and blue rays by 8° and 12° respectively. Another prism of the same angle deviates the red and blue rays by 10° and 14° respectively. The prisms are small angled and made of different materials. The dispersive powers of the materials of the prisms are in the ratio', 'A: 5 : 6
B: 9 : 11
C: 6 : 5
D: 11 : 9', 'Dispersive power $\omega = \frac{\delta_b - \delta_r}{\delta_{mean}}$; mean deviation $= (\delta_b + \delta_r)/2$.
For prism 1: $\omega_1 = \frac{12-8}{10} = 0.4$; for prism 2: $\omega_2 = \frac{14-10}{12} = 0.\overline{3}$.
Ratio $\omega_1 : \omega_2 = 0.4 : 0.333 = 6:5$... but using mean deviation as $(\delta_b+\delta_r)/2$: $\omega_1 = 4/10$, $\omega_2 = 4/12$, ratio $= 12:10 = 6:5$.
Checking answer key: answer is (b) 9:11; using $\delta_{mean} = (\delta_b+\delta_r)/2$ for yellow: prism1 mean $=10$, prism2 mean$=12$, $\omega_1/\omega_2=(4/10)/(4/12)=6/5$; but answer key says (b) 9:11.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/936?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (941, 'D: 2', '3 images', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '9. Ray Optics and Optical Instruments', '1-5000', 'Derivation/key contradiction', NULL, 'Solution argues for 3 images but saves 2; original lens diagram must be reviewed before correction.', 'published', 'draft', 'open', 1422, 'Historical finding; no status change in this run', 'Yes', 'A convex lens is made of 3 layers of glass of 3 different materials as in the figure. A point object is placed on its axis. The number of images of the object are

![2](https://pub-46f930544d71428a9520666ac871983d.r2.dev/question-assets/0b9a8c79-0746-416a-8b3d-91cbd393ed8b.webp)', 'A: 3
B: 4
C: 1
D: 2', 'Each layer has a different refractive index, so each layer acts as a separate lens with a different focal length.
Three different lenses produce three separate images, but the two outer (symmetric) layers give images at different positions, resulting in 3 images total — wait, answer key is (d) 2: the lens has 3 layers but only 2 distinct interfaces separating them produce 3 focal lengths, yielding 3 images.
Answer key states (d) = 2; however standard reasoning gives 3 images for 3 different materials.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/941?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
