INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (1334, 'A: $\text{I}_3^-,\, \text{H}_2\text{O}$', 'I3− has 3 central lone pairs', 'Human validation required; screening is not an Answer Audit', 'Chemistry', 'CET', '4. Chemical Bonding and Molecular Structure', '1-5000', 'Derivation/key contradiction', NULL, 'Solution admits I3− does not meet the stated two-lone-pair condition but keeps its keyed pair.', 'published', 'draft', 'open', 1429, 'Historical finding; no status change in this run', 'Yes', 'Which of the following pairs contains 2 lone pairs of electrons on the central atom?', 'A: $\text{I}_3^-,\, \text{H}_2\text{O}$
B: $\text{H}_2\text{O},\, \text{NF}_3$
C: $\text{XeF}_4,\, \text{NH}_3$
D: $\text{SO}_4^{2-},\, \text{H}_2\text{S}$', '$\text{I}_3^-$: central I has 3 lone pairs... wait — $\text{I}_3^-$ has 2 lone pairs on central I (5 electron pairs total, 2 bonding, 3 lone — actually 3 lone pairs). Reconsidering: $\text{H}_2\text{O}$ has 2 lone pairs on O.
$\text{I}_3^-$ has 3 lone pairs on central I, but the answer key gives (a). The source explanation shows both as ''Bent or V-shape'' suggesting 2 lone pairs each (as in bent geometry). Hence option (a) is taken as per the answer key.

![Structure diagrams of I3- and H2O showing lone pairs on central atoms in bent or V-shape geometry](https://pub-46f930544d71428a9520666ac871983d.r2.dev/question-assets/48d4d12b-ccae-4b7a-9521-d87a3a07b1b8.png)', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/1334?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (1419, 'A: addition of A', 'A, B and C', 'Human validation required; screening is not an Answer Audit', 'Chemistry', 'CET', '6. Equilibrium', '1-5000', 'Multiple accepted answers claimed; saved set differs', NULL, 'Explanation claims three changes leave equilibrium constant unchanged, but only A is stored.', 'published', 'draft', 'open', 1430, 'Historical finding; no status change in this run', 'Yes', 'For the reaction $A_{(g)} + B_{(g)} \rightleftharpoons C_{(g)} + D_{(g)}$; $\Delta H = -Q$ kJ. The equilibrium constant cannot be disturbed by', 'A: addition of A
B: addition of D
C: increasing of pressure
D: increasing of temperature', 'The equilibrium constant $K$ changes only with temperature; pressure and concentration changes shift the position of equilibrium but do not change $K$.
However, question asks what cannot disturb equilibrium — options (a), (b), (c) all disturb the equilibrium position but not $K$; only temperature (d) changes $K$ itself.
The answer key gives (a,b,c) as correct — meaning equilibrium constant cannot be changed by addition of A, addition of D, or increasing pressure; hence options (a), (b), (c) are correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/1419?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (1517, 'C: $K_H$ value increases on increasing the temperature of the solution.', 'C and D', 'Human validation required; screening is not an Answer Audit', 'Chemistry', 'CET', '1. Solutions', '1-5000', 'Multiple accepted answers claimed; saved set differs', NULL, 'Explanation declares both Henry-law statements correct but only C is stored.', 'published', 'draft', 'open', 1431, 'Historical finding; no status change in this run', 'Yes', 'Choose the correct statement.', 'A: $K_H$ value is same for a gas in any solution.
B: Higher the $K_H$ value more the solubility of gas.
C: $K_H$ value increases on increasing the temperature of the solution.
D: Easily liquefiable gases usually have lesser $K_H$ values.', '$K_H$ depends on the nature of gas and solvent, and increases with temperature (solubility decreases with temperature).
Easily liquefiable gases are more soluble and have lower $K_H$ values — both (c) and (d) are correct, which matches the answer key marking (c,d).
Hence options (c) and (d) are correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/1517?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (1532, 'A: 2 N', '0.002 N according to derivation', 'Human validation required; screening is not an Answer Audit', 'Chemistry', 'CET', '2. Electrochemistry', '1-5000', 'Derivation/key contradiction', NULL, 'Solution identifies 0.002 N as least specific conductance, then reverses to 2 N to follow the key.', 'published', 'draft', 'open', 1432, 'Historical finding; no status change in this run', 'Yes', 'Which of the following electrolytic solutions has the least specific conductance?', 'A: 2 N
B: 0.002 N
C: 0.02 N
D: 0.2 N', 'Specific conductance increases with increasing concentration because more ions are present per unit volume.
The highest concentration (2 N) has the most ions, so it has the highest specific conductance — wait, re-reading: the question asks for LEAST specific conductance.
Among the options, 2 N has the highest concentration and thus the highest specific conductance; 0.002 N has the least.
However, the answer key gives (a) 2 N — this matches the book''s explanation that 2 N has the least specific conductance due to interionic interactions at high concentration. Hence option (a) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/1532?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (1548, 'C: $\ce{PbSO4}$ on anode is reduced to Pb', 'Cathode reduction, not anode reduction', 'Human validation required; screening is not an Answer Audit', 'Chemistry', 'CET', '2. Electrochemistry', '1-5000', 'Derivation/key contradiction', NULL, 'Solution''s own charging reactions contradict the saved anode-reduction option; more than one listed charging statement may be valid.', 'published', 'draft', 'open', 1433, 'Historical finding; no status change in this run', 'Yes', 'While charging the lead storage battery', 'A: $\ce{PbSO4}$ on cathode is reduced to Pb
B: $\ce{PbSO4}$ on anode is oxidized to $\ce{PbO2}$
C: $\ce{PbSO4}$ on anode is reduced to Pb
D: $\ce{PbSO4}$ on cathode is oxidized to Pb', 'During charging, the cell acts as an electrolytic cell; the anode reaction is reversed: $\ce{PbSO4}$ at the anode loses electrons and is reduced back — wait, the book''s key says (c): $\ce{PbSO4}$ on anode is reduced to Pb.
During charging: cathode: $\ce{PbSO4 + 2e^- -> Pb + SO4^{2-}}$ (reduction); anode: $\ce{PbSO4 + 2H2O -> PbO2 + SO4^{2-} + 4H^+ + 2e^-}$ (oxidation).
So the correct charging reaction is $\ce{PbSO4}$ at cathode is reduced to Pb; the answer key (c) matches this.
