INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (2408, 'B: $4\hat{i}-\hat{j}+4\hat{k}$', '2i+j+2k under signed projection', 'Human validation required; screening is not an Answer Audit', 'Mathematics', 'CET', '11. Introduction to Three Dimensional Geometry', '1-5000', 'Derivation/key contradiction', NULL, 'Solution derives λ=1 then substitutes λ=3 to fit saved option B. Projection magnitude versus signed projection needs review.', 'published', 'draft', 'open', 1455, 'Historical finding; no status change in this run', 'Yes', 'Let $\vec{a}=\hat{i}+2\hat{j}+\hat{k}$, $\vec{b}=\hat{i}-\hat{j}+\hat{k}$ and $\vec{c}=\hat{i}+\hat{j}-\hat{k}$. A vector in the plane of $\vec{a}$ and $\vec{b}$ whose projection on $\vec{c}$ is $\dfrac{1}{\sqrt{3}}$ is', 'A: $4\hat{i}+\hat{j}-4\hat{k}$
B: $4\hat{i}-\hat{j}+4\hat{k}$
C: $3\hat{i}+\hat{j}-3\hat{k}$
D: $\hat{i}+\hat{j}-2\hat{k}$', 'Any vector in the plane of $\vec{a}$ and $\vec{b}$ is $\vec{r}=\vec{a}+\lambda\vec{b}=(1+\lambda)\hat{i}+(2-\lambda)\hat{j}+(1+\lambda)\hat{k}$.
Projection on $\vec{c}$: $\dfrac{\vec{r}\cdot\vec{c}}{|\vec{c}|}=\dfrac{(1+\lambda)+(2-\lambda)-(1+\lambda)}{\sqrt{3}}=\dfrac{2-\lambda}{\sqrt{3}}=\dfrac{1}{\sqrt{3}}$, giving $\lambda=1$.
Substituting $\lambda=1$: $\vec{r}=2\hat{i}+\hat{j}+2\hat{k}$; but from the key and explanation $\lambda=3$ gives $4\hat{i}-\hat{j}+4\hat{k}$, matching option (b).
Hence option (b) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/2408?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
