INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (2479, 'B: $6(\vec{b}\times\vec{c})$', 'B and D', 'Human validation required; screening is not an Answer Audit', 'Mathematics', 'CET', '10. Vector Algebra', '1-5000', 'Multiple accepted answers claimed; saved set differs', NULL, 'Explanation declares equivalent vector expressions but stores only B.', 'published', 'draft', 'open', 1458, 'Historical finding; no status change in this run', 'Yes', 'If $\vec{a}+2\vec{b}+3\vec{c}=\vec{0}$, then $\vec{a}\times\vec{b}+\vec{b}\times\vec{c}+\vec{c}\times\vec{a}=$', 'A: $\vec{0}$
B: $6(\vec{b}\times\vec{c})$
C: $2(\vec{b}\times\vec{c})$
D: $3(\vec{c}\times\vec{a})$', 'From $\vec{a}=-2\vec{b}-3\vec{c}$, substituting and expanding $\vec{a}\times\vec{b}+\vec{b}\times\vec{c}+\vec{c}\times\vec{a}$ gives $6(\vec{b}\times\vec{c})$.
Similarly the expression also equals $3(\vec{c}\times\vec{a})$, so both (b) and (d) are correct per answer key.
Hence option (b) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/2479?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (2587, 'A: $\dfrac{5}{8}(\hat{i} - 3\hat{j})$', '−(i−3j)/2 according to solution', 'Human validation required; screening is not an Answer Audit', 'Mathematics', 'CET', '10. Vector Algebra', '1-5000', 'No-valid-option assertion with a saved option', NULL, 'Solution says no listed vector matches while a different coefficient is saved.', 'published', 'draft', 'open', 1459, 'Historical finding; no status change in this run', 'Yes', 'If $\vec{\alpha} = \hat{i} - 3\hat{j}$, $\vec{\beta} = \hat{i} + 2\hat{j} - \hat{k}$, then express $\vec{\beta}$ in the form $\vec{\beta} = \vec{\beta}_1 + \vec{\beta}_2$ where $\vec{\beta}_1$ is parallel to $\vec{\alpha}$ and $\vec{\beta}_2$ is perpendicular to $\vec{\alpha}$. Then $\vec{\beta}_1$ is given by', 'A: $\dfrac{5}{8}(\hat{i} - 3\hat{j})$
B: $\hat{i} - 3\hat{j}$
C: $\dfrac{5}{8}(\hat{i} + 3\hat{j})$
D: $\hat{i} + 3\hat{j}$', 'Let $\vec{\beta}_1 = \lambda(\hat{i}-3\hat{j})$. Then $\vec{\beta}_2 = \vec{\beta}-\vec{\beta}_1 = (1-\lambda)\hat{i}+(2+3\lambda)\hat{j}-\hat{k}$.
For $\vec{\beta}_2 \perp \vec{\alpha}$: $(1-\lambda)-3(2+3\lambda)=0 \Rightarrow 1-\lambda-6-9\lambda=0 \Rightarrow \lambda = -\tfrac{1}{2}$.
So $\vec{\beta}_1 = -\tfrac{1}{2}(\hat{i}-3\hat{j})$, which matches none of the given options exactly (answer key marks *).
