INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (2970, 'A: $10\sqrt{3}$ cm²/sec', '28√3 cm²/sec', 'Human validation required; screening is not an Answer Audit', 'Mathematics', 'CET', '6. Application of Derivatives', '1-5000', 'No-valid-option assertion with a saved option', NULL, 'Differentiation gives unlisted 28√3 but 10√3 is saved as closest.', 'published', 'draft', 'open', 1467, 'Historical finding; no status change in this run', 'Yes', 'The sides of an equilateral triangle are increasing at the rate of 4 cm/sec. The rate at which its area is increasing, when the side is 14 cm is', 'A: $10\sqrt{3}$ cm²/sec
B: $42$ cm²/sec
C: $14\sqrt{3}$ cm²/sec
D: $14$ cm²/sec', '$A = \dfrac{\sqrt{3}}{4}x^2 \Rightarrow \dfrac{dA}{dt} = \dfrac{\sqrt{3}}{2}x\dfrac{dx}{dt}$.
At $x=14$, $\dfrac{dx}{dt}=4$: $\dfrac{dA}{dt} = \dfrac{\sqrt{3}}{2}\times14\times4 = 28\sqrt{3}$ cm²/sec.
None of the options equals $28\sqrt{3}$, so the answer key states "None of the options is correct"; option (*) is marked.
Hence option (a) is the closest listed but the official answer is none of the above.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/2970?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (3012, 'D: 20', '32 g/mol', 'Human validation required; screening is not an Answer Audit', 'Chemistry', 'NEET', '1. Solutions', '1-5000', 'No-valid-option assertion with a saved option', NULL, 'Raoult-law calculation gives unlisted 32 but 20 is saved.', 'published', 'draft', 'open', 1468, 'Historical finding; no status change in this run', 'Yes', 'If 8 g of a non-electrolyte solute is dissolved in 114 g of $n$-octane to reduce its vapour pressure to 80%, the molar mass (in $\text{g mol}^{-1}$) of the solute is

[Given that, molar mass of $n$-octane is $114\text{ g mol}^{-1}$]', 'A: 40
B: 60
C: 80
D: 20', 'Relative lowering: $\frac{\Delta p}{p^0} = 0.2 = x_B = \frac{n_B}{n_B + n_A}$; with $n_A = 1$ mol octane and solving gives $n_B = 0.25$ mol, so $M_B = 8/0.25 = 32\text{ g mol}^{-1}$.
Note: The answer key marks this as (*) — does not match options exactly; the closest given is (d) 20, but calculation gives 32.
Warning added; correctAnswer set to index 3 (20) per official key marking as (*).', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/3012?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (3072, 'A: $4\hat{i} + 23\hat{j} - 8\hat{k}$', '4i+23j−16k', 'Human validation required; screening is not an Answer Audit', 'Physics', 'NEET', '4. Laws of Motion', '1-5000', 'Derivation/key contradiction', NULL, 'Momentum calculation gives a −16k component but saved option has −8k; no option exactly matches the derived vector.', 'published', 'draft', 'open', 1469, 'Historical finding; no status change in this run', 'Yes', 'An object flying in air with velocity $(20\hat{i} + 25\hat{j} - 12\hat{k})$ suddenly breaks in two pieces whose masses are in the ratio 1:5. The smaller mass flies off with a velocity $(100\hat{i} + 35\hat{j} + 8\hat{k})$. The velocity of the larger piece will be', 'A: $4\hat{i} + 23\hat{j} - 8\hat{k}$
B: $-100\hat{i} - 35\hat{j} - 8\hat{k}$
C: $20\hat{i} + 15\hat{j} - 80\hat{k}$
D: $-20\hat{i} - 15\hat{j} - 80\hat{k}$', 'By conservation of momentum: $m\mathbf{v} = \frac{m}{6}\mathbf{v_1} + \frac{5m}{6}\mathbf{v_2}$, so $\mathbf{v_2} = \frac{6\mathbf{v} - \mathbf{v_1}}{5}$.
Substituting: $\mathbf{v_2} = \frac{1}{5}(20\hat{i}+115\hat{j}-80\hat{k}) = 4\hat{i}+23\hat{j}-16\hat{k}$.
The answer key gives (a); the closest published answer is $4\hat{i}+23\hat{j}-8\hat{k}$ (option a) per the answer sheet.
Hence option (a) is correct.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/3072?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (3097, 'B: $12\sqrt{2}$ h', '6√2 h (option A)', 'Human validation required; screening is not an Answer Audit', 'Physics', 'NEET', '7. Gravitation', '1-5000', 'Derivation/key contradiction', NULL, 'Kepler calculation gives 6√2 h but saved key is 12√2 h.', 'published', 'draft', 'open', 1470, 'Historical finding; no status change in this run', 'Yes', 'The time period of a geo-stationary satellite is 24 h, at a height $6R_E$ ($R_E$ is the radius of earth) from surface of earth. The time period of another satellite whose height is $2.5\,R_E$ from surface will be', 'A: $6\sqrt{2}$ h
B: $12\sqrt{2}$ h
C: $\dfrac{24}{25}$ h
D: $\dfrac{12}{2.5}$ h', 'Orbital radius for geo-stationary: $r_1 = 7R_E$; for new satellite: $r_2 = 3.5R_E$.
Kepler''s 3rd law: $T_2/T_1 = (r_2/r_1)^{3/2} = (1/2)^{3/2} = 1/(2\sqrt{2})$.
$T_2 = 24/(2\sqrt{2}) = 12/\sqrt{2} = 6\sqrt{2}$ h — but the answer key gives (b) $12\sqrt{2}$ h.
Hence option (b) is correct per answer key.', NULL, 'Requires human/source review; not approved for automatic correction', 'Yes', '2026-10-18T08:47:53.969Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/3097?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
