INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (8075, 'A: The DNA fragments move towards anode under electric field through the matrix.', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Biology', 'CET', '9. Biotechnology: Principles and Processes', '5001-10000', 'Historical screening candidate', NULL, '{"category": "Inconsistency", "id": 8075, "quote": "The answer key gives ''G'' (grace mark) suggesting this question had an issue", "reason": "The explanation notes the question was invalid, rendering the stored key meaningless."}', 'published', 'draft', 'open', 1510, 'Historical finding; no status change in this run', 'Yes', 'Which one of the following statement is wrong with respect to separation of DNA fragments on gel electrophoresis?', 'A: The DNA fragments move towards anode under electric field through the matrix.
B: The commonly used matrix is agarose gel.
C: The DNA fragments resolve according to their size.
D: The smaller DNA fragments separate first.', 'DNA is negatively charged, so it moves towards the positive electrode (anode) — this statement is actually correct.
However, the answer key gives ''G'' (grace mark) suggesting this question had an issue; the intended wrong statement is likely option (1) because in some formulations DNA moves toward cathode — but conventionally DNA moves to anode.
According to official key, grace mark was awarded.', NULL, '{"category": "Inconsistency", "id": 8075, "quote": "The answer key gives ''G'' (grace mark) suggesting this question had an issue", "reason": "The explanation notes the question was invalid, rendering the stored key meaningless."}', 'Yes', 'Historical timestamp not recorded'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/8075?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (8079, 'A: 25%', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Biology', 'CET', '4. Principles of Inheritance and Variation', '5001-10000', 'Historical screening candidate', NULL, '{"category": "Inconsistency", "id": 8079, "quote": "But official key gives option 1 (25%); this likely assumes only X-bearing sperm are counted or genes are not independent.", "reason": "Explanation calculates 12.5% while the key forces 25%."}', 'published', 'draft', 'open', 1511, 'Historical finding; no status change in this run', 'Yes', 'A human male is heterozygous for autosomal genes ''A'' and ''B''. He is also hemizygous for haemophilic gene ''h''. What percentage of sperms will carry ''abh'' genotype?', 'A: 25%
B: 50%
C: 75%
D: 0%', 'Autosomal genes: AaBb → sperms: AB, Ab, aB, ab each with 25% frequency; ''ab'' probability = 1/4.
Hemizygous male has only ''h'' on X chromosome → all X-bearing sperm carry h; Y-bearing carry no h allele.
Probability of ''abh'' sperm = P(ab) × P(X with h) = 1/4 × 1/2 = 1/8 = 12.5%.
But official key gives option 1 (25%); this likely assumes only X-bearing sperm are counted or genes are not independent. Grace mark was awarded for Q51, so answer is approximate.
Hence option (1) 25% is the official answer.', NULL, '{"category": "Inconsistency", "id": 8079, "quote": "But official key gives option 1 (25%); this likely assumes only X-bearing sperm are counted or genes are not independent.", "reason": "Explanation calculates 12.5% while the key forces 25%."}', 'Yes', 'Historical timestamp not recorded'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/8079?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
