INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (8658, 'B: $-\ce{NR2} < -OR < -F$', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Chemistry', 'NEET', '8. Organic Chemistry — Some Basic Principles and Techniques', '5001-10000', 'Historical screening candidate', 'answer_set', '{"id": 8658, "category": "Multiple accepted answers claimed; saved set differs", "reason": "The explanation claims a different accepted-answer set. Do not automatically expand the key from this claim."}', 'published', 'draft', 'open', 1513, 'Historical finding; no status change in this run', 'Yes', 'Which of the following is correct with respect to $-I$ effect of the substituents? ($R$ = alkyl)', 'A: $-\ce{NH2} > -OR > -F$
