INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (8911, 'D: $-1.6$ m s$^{-1}$, 8 N', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'NEET', '4. Laws of Motion', '5001-10000', 'Historical screening candidate', 'no_matching_option', '{"category": "Inconsistency", "id": 8911, "quote": "The answer key gives (*) for Q29, meaning none of the options is correct per the source.", "reason": "Explanation explicitly states that no valid answer exists among the choices."}', 'published', 'draft', 'open', 1514, 'Historical finding; no status change in this run', 'Yes', 'A person holding a rifle (mass of person and rifle together is 100 kg) stands on a smooth surface and fires 10 shots horizontally, in 5 s. Each bullet has a mass of 10 g with a muzzle velocity of 800 m s$^{-1}$. The final velocity acquired by the person and the average force exerted on the person are', 'A: $-0.08$ m s$^{-1}$, 16 N
B: $-0.8$ m s$^{-1}$, 8 N
