INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (14864, 'B: $[M^1L^{11}T^{-2}]$', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '1. Units and Measurements', '10001-15000', 'No-valid-option assertion with a saved option', NULL, 'The dimensional derivation gives an L exponent 11/2, then changes it to 11 as supposed rounding to accept B. Dimensional exponents cannot be rounded that way.', 'published', 'published', 'open', 1843, 'Historical finding; no status change in this run', 'Yes', 'The potential energy U of a particle varies with distance x from a fixed origin as $U = \frac{A\sqrt{x}}{x^2 + B}$ where A and B are dimensional constants. The dimensional formula for AB is', 'A: $[M^1L^7T^{-2}]$
B: $[M^1L^{11}T^{-2}]$
C: $[M^1L^5T^{-2}]$
D: $[M^1L^9T^{-2}]$', 'U has dimension $[ML^2T^{-2}]$. For $\frac{A\sqrt{x}}{x^2+B}$ to be dimensionally consistent, B must have dimension $[L^2]$ and $A\sqrt{x}$ must have dimension of $U \times (x^2+B)$.
