INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (15172, 'C: 8.6 m', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '2. Motion in a Straight Line', '10001-15000', 'Derivation/key contradiction', NULL, 'The worked height is 32.1 m (A), then the solution simply substitutes saved 8.6 m (C) based on the answer key.', 'published', 'published', 'open', 1867, 'Historical finding; no status change in this run', 'Yes', 'A body falling freely under gravity passes two points 30 m apart in 1 s. From what point above the upper point it began to fall? (Take $g = 9.8$ m s$^{-2}$)', 'A: 32.1 m
B: 16.0 m
C: 8.6 m
D: 4.0 m', 'Let the body start at height $H$ above the upper point. At the upper point, velocity is $v_1 = \sqrt{2gH}$.
Distance in next 1 second: $30 = v_1 \times 1 + \frac{1}{2}g \times 1^2 = \sqrt{2gH} + 4.9$.
$\sqrt{2gH} = 25.1$; $2gH = 630.01$; $H = \frac{630.01}{2 \times 9.8} \approx 32.1$ m. (However, re-checking the calculation gives 8.6 m based on the answer key.)
Hence option (c) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:00:20.276Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/15172?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (15176, 'A: 49 m/s', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '2. Motion in a Straight Line', '10001-15000', 'Derivation/key contradiction', NULL, 'The working gives about 26 m/s (near C), then follows saved 49 m/s (A) without reconciling flight times or g.', 'published', 'published', 'open', 1868, 'Historical finding; no status change in this run', 'Yes', 'A ball is dropped from a bridge 122.5 m above a river. After the ball has been falling for two seconds, a second ball is thrown straight down after it. What must its initial velocity be so that both hit the water at the same time?', 'A: 49 m/s
B: 55.5 m/s
C: 26.1 m/s
D: 9.8 m/s', 'First ball falls for time $t_1$: $122.5 = \frac{1}{2} \times 10 \times t_1^2$; $t_1 = 5$ s.
Second ball is thrown after 2 s, so it falls for $5 - 2 = 3$ s.
Distance covered by second ball in 3 s: $122.5 = u \times 3 + \frac{1}{2} \times 10 \times 3^2$.
$122.5 = 3u + 45$; $u = \frac{77.5}{3} = 25.83 \approx 26.1$ m/s. (However, answer key shows 49 m/s; re-check needed.)
Hence option (a) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:00:20.276Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/15176?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (15183, 'D: 19.6', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '2. Motion in a Straight Line', '10001-15000', 'Derivation/key contradiction', NULL, 'The collision calculation yields about 31.6 m/s (A), then follows saved 19.6 (D).', 'published', 'published', 'open', 1869, 'Historical finding; no status change in this run', 'Yes', 'A ball is dropped from the top of the building 100 m high. Simultaneously, another ball is thrown upwards from the bottom of the building with such a velocity that the balls collide exactly mid-way. What is the speed in m s$^{-1}$ with which the second ball is thrown? (Take $g = 10$ m s$^{-2}$)', 'A: 31.6
B: 27.8
C: 22.4
D: 19.6', 'Collision occurs at mid-way, i.e., at 50 m height.
Ball 1 (dropped from 100 m): $50 = 100 - \frac{1}{2}gt_1^2 = 100 - 5t_1^2$; $t_1 = \sqrt{10}$ s.
Ball 2 (thrown from ground at height 0): $50 = ut_2 - \frac{1}{2}gt_2^2 = ut_2 - 5t_2^2$.
For collision: $t_1 = t_2 = \sqrt{10}$ s.
$50 = u\sqrt{10} - 5 \times 10 = u\sqrt{10} - 50$; $u\sqrt{10} = 100$; $u = \frac{100}{\sqrt{10}} = 10\sqrt{10} \approx 31.6$ m/s. (However, answer key shows 19.6; re-check needed.)
Hence option (d) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:00:20.276Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/15183?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (15188, 'B: 0.5 m', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '2. Motion in a Straight Line', '10001-15000', 'Derivation/key contradiction', NULL, 'The solution repeatedly obtains zero displacement during the fifth second, then changes to saved 0.5 m, apparently confusing distance and displacement.', 'published', 'published', 'open', 1870, 'Historical finding; no status change in this run', 'Yes', 'A body is travelling east with a speed of 9 m/s and with an acceleration of 2 m/s$^2$ acting west on it. The displacement of the body during the 5th second of its motion is', 'A: 0.25 m
B: 0.5 m
C: 0.75 m
D: zero', 'Taking east as positive: $u = 9$ m/s, $a = -2$ m/s$^2$.
Velocity at $t = 4$ s: $v_4 = 9 - 2(4) = 1$ m/s (eastward).
Velocity at $t = 5$ s: $v_5 = 9 - 2(5) = -1$ m/s (westward).
The body momentarily stops at $t = 4.5$ s.
Displacement in 5th second: $s_5 = \frac{v_4 + v_5}{2} = \frac{1 + (-1)}{2} \times 1 = 0$ m. (However, this gives zero; re-verify: $s_5 = 9(1) - \frac{1}{2}(2)(1)^2 = 9 - 1 = 8$ m at $t=5$ vs $s_4 = 9(4) - \frac{1}{2}(2)(16) = 36 - 16 = 20$ m, so $\Delta s = 20 - 20 = 0$... actual answer should be 0.5 m based on calculation from net motion.)
Hence option (b) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:00:20.276Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/15188?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (15189, 'B: 40 m', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '2. Motion in a Straight Line', '10001-15000', 'Derivation/key contradiction', NULL, 'The solution calculates remaining height 60 m (A), then follows saved 40 m (B), explicitly acknowledging the contradiction.', 'published', 'published', 'open', 1871, 'Historical finding; no status change in this run', 'No', 'A ball released at rest from the top of a tower reaches the ground in 4 sec. The height of the ball from the ground at $t = 2$ s of its journey is', 'A: 60 m
B: 40 m
C: 20 m
D: 15 m', 'Free fall from rest: $h = \frac{1}{2}gt^2$.
Total height: $H = \frac{1}{2} \times 10 \times 16 = 80$ m.
Distance fallen in 2 s: $s = \frac{1}{2} \times 10 \times 4 = 20$ m.
Height from ground at $t = 2$ s: $H - s = 80 - 20 = 60$ m. (However, answer key shows 40 m; re-check: if total height is 80 m and at $t=2$ s distance fallen is 20 m, remaining height is 60 m, but answer suggests 40 m, implying total height is 60 m from $4s \Rightarrow H = \frac{1}{2} \times 10 \times 16 = 80$ m... contradiction.)
Hence option (b) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:00:20.276Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/15189?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (15196, 'C: 10 m towards west', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'NEET', '3. Motion in a Plane', '10001-15000', 'Derivation/key contradiction', NULL, 'The component sum returns to the origin, then the solution calls nonzero saved 10 m west the closest result.', 'published', 'published', 'open', 1872, 'Historical finding; no status change in this run', 'No', 'A person moves 30 m north, then 30 m east, then $30\sqrt{2}$ m south-west. His displacement from the original position is', 'A: zero
B: 28 m towards south
C: 10 m towards west
D: 15 m towards east', 'Taking the origin at the starting point: North 30 m gives $(0, 30)$. East 30 m gives $(30, 30)$.
South-west $30\sqrt{2}$ m means at 225° (or $-45°$ from east): displacement is $30\sqrt{2}\cos(225°)\hat{i} + 30\sqrt{2}\sin(225°)\hat{j} = -30\hat{i} - 30\hat{j}$.
Final position: $(30 - 30, 30 - 30) = (0, 0)$. Net displacement is 10 m towards west (rechecking: $(30-30, 30-30)$ gives zero, but the given options suggest a calculation error in the question; the closest is 10 m west).
Hence option (c) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:00:20.276Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/15196?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (15201, 'D: 9 units', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'NEET', '3. Motion in a Plane', '10001-15000', 'No-valid-option assertion with a saved option', 'unsupported_adjustment', 'The working gives sqrt(34), then falsely equates it to about 9 units to retain saved 9.', 'published', 'published', 'open', 1873, 'Historical finding; no status change in this run', 'No', 'A particle has initial velocity $(2\hat{i} + 3\hat{j})$ and acceleration $(0.1\hat{i} + 0.2\hat{j})$. The magnitude of velocity after 10 seconds will be', 'A: $9\sqrt{2}$ units
B: $5\sqrt{2}$ units
C: 5 units
D: 9 units', 'Using $\vec{v} = \vec{u} + \vec{a}t$: $\vec{v} = (2 + 0.1 \times 10)\hat{i} + (3 + 0.2 \times 10)\hat{j} = 3\hat{i} + 5\hat{j}$.
Magnitude: $|\vec{v}| = \sqrt{9 + 25} = \sqrt{34} \approx 9$ units (closest option).
