INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (15312, 'B: -2', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '5. Work, Energy and Power', '10001-15000', 'Derivation/key contradiction', NULL, 'The dot product gives λ=3 (C) twice, then the explanation falsely says it is not offered and follows saved -2 (B).', 'published', 'published', 'open', 1887, 'Historical finding; no status change in this run', 'No', 'The value of $\lambda$ for which the two vectors $\vec{a}=5\vec{i}+\lambda\vec{j}+\vec{k}$ and $\vec{b}=\vec{i}-2\vec{j}+\vec{k}$ are perpendicular to each other is', 'A: 2
B: -2
C: 3
D: -3', 'For perpendicular vectors, $\vec{a} \cdot \vec{b} = 0$.
$(5\vec{i}+\lambda\vec{j}+\vec{k}) \cdot (\vec{i}-2\vec{j}+\vec{k}) = 0$
$5 - 2\lambda + 1 = 0 \Rightarrow \lambda = 3$
