INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (15355, 'B: $\sqrt{\frac{1}{10}\frac{m_e}{m_p}}$', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '5. Work, Energy and Power', '15001-20000', 'Derivation/key contradiction', NULL, 'Derives sqrt(mp/(10me)) (A), but the saved key uses the reciprocal mass ratio (B).', 'published', 'published', 'open', 1952, 'Historical finding; no status change in this run', 'No', 'An electron and a proton are detected in a cosmic ray experiment, the first with kinetic energy 10 keV, and the second with 100 keV. The ratio of their speeds is (where $m_e$ and $m_p$ are masses of electron and proton respectively)', 'A: $\sqrt{\frac{1}{10}\frac{m_p}{m_e}}$
B: $\sqrt{\frac{1}{10}\frac{m_e}{m_p}}$
C: $\frac{1}{10}\frac{m_e}{m_p}$
D: $\frac{1}{10}\frac{m_p}{m_e}$', '$KE_e = 10$ keV $= \frac{1}{2}m_e v_e^2 \Rightarrow v_e = \sqrt{\frac{20 \text{ keV}}{m_e}}$.
$KE_p = 100$ keV $= \frac{1}{2}m_p v_p^2 \Rightarrow v_p = \sqrt{\frac{200 \text{ keV}}{m_p}}$.
