INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (16148, 'A: $g_e > g_h > g_d$', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '7. Gravitation', '15001-20000', 'Derivation/key contradiction', NULL, 'Derives ge>gd>gh for the stated approximation, but accepts saved ge>gh>gd (A) by assuming a typo. Review the depth/height regime and missing correct option.', 'published', 'published', 'open', 2024, 'Historical finding; no status change in this run', 'No', 'If $g_e$, $g_h$ and $g_d$ be the acceleration due to gravity at earth''s surface, a height $h$ and at depth $d$ respectively ($h = d$). Then', 'A: $g_e > g_h > g_d$
B: $g_e > g_d < g_h$
C: $g_e < g_h < g_d$
D: $g_e < g_d > g_h$', 'At height $h$: $g_h = g_e(1 - 2h/R) \approx g_e(1 - 2h/R) < g_e$.
At depth $d$: $g_d = g_e(1 - d/R) \approx g_e(1 - d/R) < g_e$.
With $h = d$, we have $g_h = g_e(1 - 2d/R)$ and $g_d = g_e(1 - d/R)$.
Since $2d/R > d/R$, we get $g_h < g_d$.
Ordering: $g_e > g_d > g_h$. (Note: The question likely has a typo; the answer as written assumes $g_e > g_h > g_d$.)
Hence option (a) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/16148?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (16165, 'C: $\frac{g}{a_m} = \left(\frac{R_m}{R_E}\right)^2$', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '7. Gravitation', '15001-20000', 'Unconfirmed screening hit — contextual review did not establish a discrepancy', NULL, 'Flagged at the user''s request for validation of every screening hit, including previously excluded hits. This is NOT a confirmed mismatch or wrong answer.
