INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (17308, 'C: $8\pi/5$', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '13. Oscillations', '15001-20000', 'Derivation/key contradiction', NULL, 'Derives frequency 5/(8pi), corresponding to B under the intended denominator notation, but accepts reciprocal-like 8pi/5 (C). Verify option typography too.', 'published', 'published', 'open', 2112, 'Historical finding; no status change in this run', 'No', 'The velocity of a particle executing a simple harmonic motion is 13 m/s, when its distance from the equilibrium position Q is 3 m and its velocity is 12 m/s, when it is 5 m away from Q. The frequency of the simple harmonic motion is', 'A: $5\pi/8$
B: $5/8\pi$
C: $8\pi/5$
D: $8/5\pi$', 'Using $v^2 = \omega^2(A^2 - x^2)$: $13^2 = \omega^2(A^2 - 9)$ and $12^2 = \omega^2(A^2 - 25)$. Subtracting: $169 - 144 = \omega^2 \times 16$, so $\omega^2 = 25/16$, giving $\omega = 5/4$ rad/s. Frequency $f = \omega/(2\pi) = 5/(8\pi)$. But answer key is (c) $8\pi/5$. Let me verify: from the equations, $25 = 16\omega^2$, so $\omega = 5/4$. Hmm, let me recalculate: $169 - 144 = 25 = \omega^2(A^2 - 9 - A^2 + 25) = 16\omega^2$. Yes, $\omega = 5/4$ rad/s, frequency $f = 5/(8\pi)$ Hz, which is option (b). Trusting answer key (c) may indicate a different approach.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/17308?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (17311, 'B: $2\pi$', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '13. Oscillations', '15001-20000', 'Derivation/key contradiction', NULL, 'Repeatedly derives period 4pi (C), while the saved key is 2pi (B).', 'published', 'published', 'open', 2113, 'Historical finding; no status change in this run', 'No', 'If the displacement x and velocity v of a particle executing simple harmonic motion are related through the expression $4v^2 = 25 - x^2$, then its time period is', 'A: $\pi$
B: $2\pi$
C: $4\pi$
D: $6\pi$', 'Comparing with $v^2 = \omega^2(A^2 - x^2)$: $4v^2 = 4\omega^2(A^2 - x^2)$. Given $4v^2 = 25 - x^2$, we have $4\omega^2 A^2 = 25$ and $4\omega^2 = 1$, giving $\omega^2 = 1/4$, so $\omega = 1/2$ rad/s. Period $T = 2\pi/\omega = 2\pi/(1/2) = 4\pi$ s. But let me recheck: $4v^2 = 25 - x^2$ means $v^2 = (25 - x^2)/4$. Comparing $v^2 = \omega^2(A^2 - x^2)$: $\omega^2 = 1/4$ and $A^2 = 25/4$. Thus $\omega = 1/2$, $T = 4\pi$. Answer key shows (b) $2\pi$, suggesting $\omega = 1$ rad/s.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/17311?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_stat