INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (17764, 'A: $1$ m', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '14. Waves', '15001-20000', 'Derivation/key contradiction', NULL, 'The solution identifies nodes at 2 m and 4 m and also at saved 1 m. With nodes spaced 1 m, several current options satisfy another node; review the missing restriction instead of asserting a uniquely established A.', 'published', 'published', 'open', 2132, 'Historical finding; no status change in this run', 'No', 'A wave of wavelength 2 m is reflected from a surface. If a node is formed at 3 m from the surface, then at what distance from the surface another node will be formed?', 'A: $1$ m
B: $2$ m
C: $3$ m
D: $4$ m', 'For a standing wave formed by reflection, nodes are separated by $\lambda/2$. With $\lambda = 2$ m, nodes are 1 m apart. If a node is at 3 m from the surface, the next node is at $3 - 1 = 2$ m or $3 + 1 = 4$ m. The nearest other node at a different distance is 1 m away from the surface (i.e., at $3 - 2 = 1$ m or closer node to the surface).', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/17764?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (17775, 'B: 4', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '14. Waves', '15001-20000', 'Derivation/key contradiction', NULL, 'Derives six tones (D) and references D in the solution, while the actual saved key is four (B).', 'published', 'published', 'open', 2133, 'Historical finding; no status change in this run', 'Yes', 'If speed of sound in air is 330 m s⁻¹, then find the number of tones present in an open organ pipe of length 1 m whose frequency $f \le 1000$.', 'A: 2
B: 4
C: 8
D: 6', 'For an open pipe, fundamental $f_1 = \frac{v}{2L} = \frac{330}{2 \times 1} = 165$ Hz.
Harmonics: $n \times 165$ Hz where $n \times 165 \le 1000$, so $n \le 6.06$.
Tones are $n = 1, 2, 3, 4, 5, 6$ giving 165, 330, 495, 660, 825, 990 Hz—all ≤ 1000 Hz.
So 6 tones are present.
Source options show answer as 6, but (b) is 4. Checking source: answer key shows (d) = 6.
Actual answer is 6 tones, but marked option differs; confidence reduced.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/17775?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (17788, 'B: $\frac{2}{3}$ cm', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '14. Waves', '15001-20000', 'Unconfirmed screening hit — contextual review did not establish a discrepancy', NULL, 'Flagged at the user''s request for validation of every screening hit, including previously excluded hits. This is NOT a confirmed mismatch or wrong answer.
Screening trigger: Broad lexical screen matched: Closest
Prior contextual-review reason: The final e=1.2r convention can represent total correction at the two open ends and supports saved 2/3 cm; the per-end alternative does not by itself disprove it.
Validate the current key and retained explanation; preserve correct answers, normal approximations and resolved self-corrections.', 'published', 'published', 'open', 2370, 'Historical finding; no status change in this run', 'No', 'If the end correction of an open pipe is 0.8 cm then the inner radius of that pipe will be', 'A: $\frac{1}{3}$ cm
B: $\frac{2}{3}$ cm
C: $\frac{3}{2}$ cm
D: 0.2 cm', 'End correction for an open pipe is approximately $e \approx 0.6r$, where $r$ is the inner radius.
Given $e = 0.8$ cm: $0.8 = 0.6r$, so $r = \frac{0.8}{0.6} = \frac{4}{3}$ cm.
Alternatively, if $e \approx 0.3d$ (diameter): $0.8 = 0.3 \times 2r$, so $r = \frac{0.8}{0.6} = \frac{4}{3}$ cm.
Closest to given options: if using $e = 1.2r$ instead, $r = \frac{0.8}{1.2} = \frac{2}{3}$ cm.
Hence option (b) is correct.', NULL, 'All-rule screening validation requested; previously excluded; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/17788?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (17799, 'D: 156', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '14. Waves', '15001-20000', 'Derivation/key contradiction', NULL, 'Derives last-fork frequency 152 Hz (B), while the saved key is 156 (D).', 'published', 'published', 'open', 2134, 'Historical finding; no status change in this run', 'No', 'A set of 20 tuning forks is arranged in a series of increasing frequencies. If each fork gives 4 beats with respect to the preceding fork and the frequency of the last fork is twice the frequency of the first, then the frequency of last fork is (in Hz).', 'A: 148
B: 152
C: 154
D: 156', 'Let first fork frequency = $f$. Each successive fork differs by 4 Hz.
Frequencies: $f, f+4, f+8, ..., f+4(19) = f+76$.
Given last = $2 \times$ first: $f + 76 = 2f$, so $f = 76$ Hz.
Last fork frequency: $2 \times 76 = 152$ Hz.
Wait, re-check: option (d) is 156. Let me recalculate: if $f+76 = 2f$, then $f=76$ and $2f=152$. But answer key shows 156.
Possibly: 20 forks means 19 intervals, each 4 Hz. So $f + 19 \times 4 = 2f$ gives $f = 76$, last = 152 Hz (option b).
But marked answer is (d). Confidence reduced.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/17799?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (17800, 'A: 251 Hz', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '14. Waves', '15001-20000', 'Unsupported adjustment / explanation defect; key not proven wrong', NULL, 'The explanation incorrectly equates the difference between the two wire frequencies to one beat frequency, gets 95 Hz, then asserts approximately 250/251 Hz (A) without a derivation. Review the two fork-wire beat conditions; do not treat the intermediate 95 as a replacement key.', 'published', 'published', 'open', 2135, 'Historical finding; no status change in this run', 'No', '5 beats/second are heard when a tuning fork is sounded with a sonometer wire under tension, when the length of the sonometer wire is either 0.95 m or 1 m. The frequency of the fork will be', 'A: 251 Hz
B: 300 Hz
C: 195 Hz
D: 150 Hz', 'Frequency of wire: $f = \frac{1}{2L}\sqrt{\frac{T}{\mu}}$. Frequency is inversely proportional to length.
At $L_1 = 0.95$ m: $f_1 = \frac{k}{0.95}$; at $L_2 = 1$ m: $f_2 = \frac{k}{1} = k$.
Beat frequency: $|f_1 - f_2| = 5$ → $|\frac{k}{0.95} - k| = 5$.
$k(\frac{1}{0.95} - 1) = 5$ → $k \times \frac{0.05}{0.95} = 5$ → $k = \frac{5 \times 0.95}{0.05} = 95$ Hz.
Wait, this gives 95 Hz, not matching options. Re-approach: $\frac{k}{0.95} - \frac{k}{1} = \frac{k \times 0.05}{0.95} = 5$ → $k = 95$ Hz.
But fork frequency is between or near the two wire frequencies. At equilibrium: fork ≈ 250 Hz fits option (a).
Actual calculation suggests answer (a) 251 Hz is closest.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/17800?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (17802, 'C: 420 Hz', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '14. Waves', '15001-20000', 'Unconfirmed screening hit — contextual review did not establish a discrepancy', NULL, 'Flagged at the user''s request for validation of every screening hit, including previously excluded hits. This is NOT a confirmed mismatch or wrong answer.
Screening trigger: Broad lexical screen matched: contradict
Prior contextual-review reason: Read stem, current options/key and full retained explanation: the lexical hit does not establish an unresolved derivation-versus-current-key conflict under this screening scope.
Validate the current key and retained explanation; preserve correct answers, normal approximations and resolved self-corrections.', 'published', 'published', 'open', 2371, 'Historical finding; no status change in this run', 'No', 'Two sitar strings, A and B, playing the note ''Dha'' are slightly out of tune and produce beats of frequency 5 Hz. The tension of the string B is slightly increased and the beat frequency is found to decrease by 3 Hz. If the frequency of A is 425 Hz, the original frequency of B is', 'A: 428 Hz
B: 430 Hz
C: 420 Hz
D: 422 Hz', 'Initial: $|f_A - f_B| = 5$ → $|425 - f_B| = 5$ → $f_B = 420$ Hz or 430 Hz.
Increasing tension increases frequency. Beats decrease from 5 to 2 Hz.
If $f_B = 420$ Hz: increasing tension brings it closer to 425; new beats = 2 Hz → $f_B'' \approx 423$ Hz.
Check: $|425 - 423| = 2$ Hz. ✓ Beat decrease = 5 - 2 = 3 Hz. ✓
If $f_B = 430$ Hz: increasing tension increases it further, away from 425, contradicting beat decrease.
Therefore $f_B = 420$ Hz.
Hence option (c) is correct.', NULL, 'All-rule screening validation requested; previously excluded; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/17802?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (17805, 'C: 8 beats per second with intensity ratio 81 : 1 between waxing and waning.', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '14. Waves', '15001-20000', 'Derivation/key contradiction', NULL, 'Derives four beats per second and intensity ratio 81:1 (D), while the saved key C has eight beats.', 'published', 'published', 'open', 2136, 'Historical finding; no status change in this run', 'No', 'Two sources of sound placed close to each other, are emitting progressive waves given by $y_1 = 4\sin(600\pi t)$ and $y_2 = 5\sin(608\pi t)$. An observer located near these two sources of sound will hear', 'A: 4 beats per second with intensity ratio 25 : 16 between waxing and waning.
B: 8 beats per second with intensity ratio 25 : 16 between waxing and waning.
C: 8 beats per second with intensity ratio 81 : 1 between waxing and waning.
D: 4 beats per second with intensity ratio 81 : 1 between waxing and waning.', 'From $y_1 = 4\sin(600\pi t)$: $f_1 = \frac{600}{2} = 300$ Hz.
From $y_2 = 5\sin(608\pi t)$: $f_2 = \frac{608}{2} = 304$ Hz.
Beat frequency: $|f_2 - f_1| = 4$ Hz. But checking again: $600\pi = 2\pi f_1$ → $f_1 = 300$ Hz; $608\pi = 2\pi f_2$ → $f_2 = 304$ Hz.
