INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (19182, 'C: $25\ \Omega$', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '7. Alternating Current', '15001-20000', 'Derivation/key contradiction', NULL, 'Repeated calculation gives resistance about 16 ohm, but the explanation asserts source B=20, while actual saved key is C=25. Review resistance versus impedance and the option reference.', 'published', 'published', 'open', 2225, 'Historical finding; no status change in this run', 'No', 'An electrical device draws 2 kW power from AC mains voltage 223 V (rms). The current lags in phase by $\phi = \tan^{-1}\left(-\dfrac{3}{4}\right)$ as compared to voltage. The resistance $R$ in the circuit is', 'A: $15\ \Omega$
B: $20\ \Omega$
C: $25\ \Omega$
D: $30\ \Omega$', '$\cos\phi = 4/5$ (since $\tan\phi = 3/4$). $P = V_{rms}^2 \cos\phi / Z$, so $Z = V^2\cos\phi/P = 223^2 \times 0.8/2000 \approx 20\ \Omega$. $R = Z\cos\phi = 20 \times 0.8 = 16\ \Omega$... answer key gives (b) 20 Ω. Using $P = I^2 R$: $I = P/(V\cos\phi) = 2000/(223 \times 0.8) \approx 11.2$ A; $R = P/I^2 = 2000/125.4 \approx 16\ \Omega$. Answer key gives (b) 20 Ω.
Per the answer key, option (b) $20\ \Omega$ is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/19182?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (19189, 'A: 375 W', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '7. Alternating Current', '15001-20000', 'Derivation/key contradiction', NULL, 'The multiplication 75000 times 0.5 is falsely written as 375 rather than 37500 (C), supporting saved 375 (A). A speculative current-unit typo does not resolve the stated values.', 'published', 'published', 'open', 2226, 'Historical finding; no status change in this run', 'No', 'In an AC circuit, $V$ and $I$ are given by $V = 300\sin(150t)$ volt and $I = 500\sin\left(150t + \dfrac{\pi}{3}\right)$ ampere. The power dissipated in the circuit is', 'A: 375 W
B: 3750 W
C: 37500 W
D: zero', 'Phase difference $\phi = \pi/3$. $P = \dfrac{V_0 I_0}{2}\cos\phi = \dfrac{300 \times 500}{2} \times \cos(60°) = 75000 \times 0.5 = 375$ W. Wait: units of I are ampere (likely mA or typo, but taking as given). Answer key gives (a) 375 W.
Hence option (a) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/19189?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
