INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (20151, 'A: 3.4 eV', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '12. Atoms', '15001-20000', 'Derivation/key contradiction', NULL, 'The explanation initially derives n=3 and kinetic energy about 1.5 eV (B), then changes the virial relation and reinterprets second excited as first excited to force saved 3.4 eV (A).', 'published', 'published', 'open', 2280, 'Historical finding; no status change in this run', 'No', 'The total energy of electron in the ground state of hydrogen atom is $-13.6$ eV. The kinetic energy of an electron in the second excited state is', 'A: 3.4 eV
B: 1.5 eV
C: 13.6 eV
D: 1.7 eV', 'In the second excited state, $n = 3$. Total energy $E_3 = \frac{-13.6}{9}$ eV ≈ $-1.51$ eV.
By the virial theorem for hydrogen, kinetic energy $K = -E$ and potential energy $U = 2E$.
So $K = -(-1.51) = 1.51$ eV ≈ 1.5 eV... but checking: for $n=3$, $E = -13.6/9 \approx -1.51$ eV, and $K = |E| \times 2 / 2 = |E|$ is incorrect. Correct: $K = -2E = 2 \times 1.51 \approx 3.02$ eV, closer to 3.4 eV given rounding in the second excited state ($n=3$: $-13.6/9 \approx -1.51$ gives $K \approx 3.0$; but for first excited ($n=2$): $K = 3.4$ eV).
Option (a) suggests first excited state ($n=2$), so the question likely intends $n=2$; then $K = -2E_{n=2} = -2(-13.6/4) = 6.8/2 = 3.4$ eV.
Hence option (a) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/20151?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (20158, 'C: 12.3 nm', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '12. Atoms', '15001-20000', 'Derivation/key contradiction', NULL, 'Repeatedly derives excitation wavelength 10.8 nm, explicitly offered as A, then falsely calls saved 12.3 (C) closest or a more careful recalculation.', 'published', 'published', 'open', 2281, 'Historical finding; no status change in this run', 'No', 'In $\ce{Li^{2+}}$, electron in first Bohr orbit is excited to a level by a radiation of wavelength $\lambda$. When the ion gets deexcited to the ground state in all possible ways (including intermediate emissions), a total of six spectral lines are observed. What is the value of $\lambda$? (Given: $h = 6.63 \times 10^{-34}$ J s; $c = 3 \times 10^8$ m s$^{-1}$)', 'A: 10.8 nm
B: 11.4 nm
C: 12.3 nm
D: 9.4 nm', 'Number of spectral lines from transitions ending at ground state starting from level $n$ is $\frac{n(n-1)}{2} = 6$, giving $n(n-1) = 12$, so $n = 4$.
For $\ce{Li^{2+}}$ (Z=3), excitation energy from $n=1$ to $n=4$: $\Delta E = 13.6 \times 9 (1 - 1/16) = 122.4 \times 15/16 \approx 114.75$ eV.
$\lambda = \frac{hc}{\Delta E} = \frac{1240}{114.75} \approx 10.8$ nm... checking: $122.4(1-1/16) = 122.4 \times 15/16 = 114.75$ eV, giving $\lambda \approx 10.8$ nm, but option closest is 12.3. Recalculating more carefully suggests option (c).
Hence option (c) is correct.', NULL, 'Potential candidate — human review required; no correction approved', 'Yes', '2026-10-18T11:20:07.709Z'::timestamptz, '2026-10-18T12:34:15.495Z'::timestamptz, 'https://app.ilearn-india.com/admin/questions/20158?from=bank') ON CONFLICT (qid) DO UPDATE SET "answer_key" = EXCLUDED."answer_key", "solution_key_review_result" = EXCLUDED."solution_key_review_result", "review_status" = EXCLUDED."review_status", "subject" = EXCLUDED."subject", "exam" = EXCLUDED."exam", "chapter" = EXCLUDED."chapter", "screening_batch_existing_question_ordinal" = EXCLUDED."screening_batch_existing_question_ordinal", "category" = EXCLUDED."category", "deterministic_rules" = EXCLUDED."deterministic_rules", "question_specific_finding_evidence" = EXCLUDED."question_specific_finding_evidence", "publication_status_at_screening" = EXCLUDED."publication_status_at_screening", "current_publication_status" = EXCLUDED."current_publication_status", "flag_status" = EXCLUDED."flag_status", "flag_id" = EXCLUDED."flag_id", "action_in_this_10k_run" = EXCLUDED."action_in_this_10k_run", "exam_linked" = EXCLUDED."exam_linked", "question" = EXCLUDED."question", "options" = EXCLUDED."options", "stored_explanation" = EXCLUDED."stored_explanation", "numeric_answer_policy" = EXCLUDED."numeric_answer_policy", "original_review_status_context" = EXCLUDED."original_review_status_context", "content_unchanged_since_screening" = EXCLUDED."content_unchanged_since_screening", "screened_at_utc" = EXCLUDED."screened_at_utc", "live_status_checked_at_utc" = EXCLUDED."live_status_checked_at_utc", "question_url" = EXCLUDED."question_url";
INSERT INTO public.screening_findings_import ("qid", "answer_key", "solution_key_review_result", "review_status", "subject", "exam", "chapter", "screening_batch_existing_question_ordinal", "category", "deterministic_rules", "question_specific_finding_evidence", "publication_status_at_screening", "current_publication_status", "flag_status", "flag_id", "action_in_this_10k_run", "exam_linked", "question", "options", "stored_explanation", "numeric_answer_policy", "original_review_status_context", "content_unchanged_since_screening", "screened_at_utc", "live_status_checked_at_utc", "question_url") VALUES (20163, 'C: both (a) and (b)', 'Not independently determined; inspect the stored solution', 'Human validation required; screening is not an Answer Audit', 'Physics', 'CET', '12. Atoms', '15001-20000', 'Unconfirmed screening hit — contextual review did not establish a discrepancy', NULL, 'Flagged at the user''s request for validation of every screening hit, including previously excluded hits. This is NOT a confirmed mismatch or wrong answer.
